import { test, expect } from '@playwright/test';

test.describe('Modal Title Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should announce modal title when modal is opened', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal title is announced
    await expect(page).toHaveRole('alert');
    await expect(page).toHaveText(/Modal Title/i);

    // Verify modal content is visible
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();
  });

  test('should not announce modal title when modal is closed', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal title is announced
    await expect(page).toHaveRole('alert');
    await expect(page).toHaveText(/Modal Title/i);

    // Close modal using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify modal title is no longer announced
    await expect(page).not.toHaveRole('alert');

    // Verify modal content is no longer visible
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).not.toBeVisible();
  });
});
